def quickCube(self, center, radius, material, is_hollow):
    p1 = Matrix3.from_euler_angles(yaw_degrees=45, pitch_degrees=0, roll_degrees=0) @ (Matrix3.from_euler_angles(yaw_degrees=0, pitch_degrees=0, roll_degrees=45) @ Vec3(radius, 0, 0))
    self.action_implementer.set_blocks(p1=(center + p1), p2=(center - p1), block_type=material)
    if is_hollow:
        p2 = Matrix3.from_euler_angles(yaw_degrees=45, pitch_degrees=0, roll_degrees=0) @ (Matrix3.from_euler_angles(yaw_degrees=0, pitch_degrees=0, roll_degrees=45) @ Vec3((radius - 2), 0, 0))
        self.action_implementer.set_blocks(p1=(center + p2), p2=(center - p2), block_type='AIR')
